def compile_manuscript():
    tmpl = build_manuscript_template()
    # Split at ## Figure Legends so we assign reference IDs 1..N strictly by first appearance in body_main
    leg_idx = tmpl.index("## Figure Legends")
    body_part = tmpl[:leg_idx]
    rest_part = tmpl[leg_idx:]

    ref_order = {}

    def repl_tag(match):
        keys = [k.strip() for k in match.group(1).split(",") if k.strip()]
        nums = []
        for k in keys:
            if k not in REF_DB:
                raise KeyError(f"Unknown reference key: {k}")
            if k not in ref_order:
                ref_order[k] = len(ref_order) + 1
            nums.append(ref_order[k])
        return format_num_list(nums)

    compiled_body = re.sub(r"\[\[REF:([^\]]+)\]\]", repl_tag, body_part)
    compiled_rest = re.sub(r"\[\[REF:([^\]]+)\]\]", repl_tag, rest_part)

    # Check if all keys in REF_DB were cited
    uncited = set(REF_DB.keys()) - set(ref_order.keys())
    if uncited:
        print("WARNING: Uncited keys in REF_DB:", uncited)

    # Build ## References section in exact order 1..N
    ref_lines = ["", "## References"]
    for k, idx in sorted(ref_order.items(), key=lambda kv: kv[1]):
        ref_lines.append(f"{idx}. {REF_DB[k]}")
    ref_lines.append("")

    full_md = compiled_body + compiled_rest + "\n".join(ref_lines)
    with open(MS_MD, "w", encoding="utf-8") as f:
        f.write(full_md)
    print(f"Compiled {MS_MD} with {len(ref_order)} strictly monotonic references.")


